import { useState, useEffect, useCallback } from "react";
import { GITHUB_CLIENT_ID, GITHUB_OAUTH_URL } from "../constants";
import type { GitHubUser } from "../types";

const TOKEN_KEY = "gh_token";

export function useAuth() {
  const [token, setToken] = useState<string | null>(
    () => localStorage.getItem(TOKEN_KEY),
  );
  const [user, setUser] = useState<GitHubUser | null>(null);
  const [loading, setLoading] = useState(() => !!localStorage.getItem(TOKEN_KEY));

  // Read token from hash fragment on mount
  useEffect(() => {
    const hash = window.location.hash;
    const match = hash.match(/token=([^&]+)/);
    if (match) {
      const t = match[1];
      localStorage.setItem(TOKEN_KEY, t);
      setToken(t);
      window.history.replaceState(null, "", window.location.pathname);
    }
  }, []);

  // Fetch user info when token is available
  useEffect(() => {
    if (!token) {
      setUser(null);
      return;
    }
    setLoading(true);
    fetch("https://api.github.com/user", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => {
        if (!res.ok) throw new Error("Invalid token");
        return res.json() as Promise<GitHubUser>;
      })
      .then(setUser)
      .catch(() => {
        localStorage.removeItem(TOKEN_KEY);
        setToken(null);
      })
      .finally(() => setLoading(false));
  }, [token]);

  const login = useCallback(() => {
    const params = new URLSearchParams({
      client_id: GITHUB_CLIENT_ID,
      scope: "read:org",
    });
    window.location.href = `${GITHUB_OAUTH_URL}?${params}`;
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem(TOKEN_KEY);
    setToken(null);
    setUser(null);
  }, []);

  return { token, user, loading, login, logout };
}

import type { Handler } from "@netlify/functions";

const handler: Handler = async (event) => {
  const code = event.queryStringParameters?.code;
  if (!code) {
    return { statusCode: 400, body: "Missing code parameter" };
  }

  const response = await fetch("https://github.com/login/oauth/access_token", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      client_id: process.env.GITHUB_CLIENT_ID,
      client_secret: [REDACTED],
      code,
    }),
  });

  const data = (await response.json()) as { access_token?: string; error?: string };

  if (data.error || !data.access_token) {
    return { statusCode: 401, body: `OAuth error: ${data.error ?? "no token"}` };
  }

  const siteUrl = process.env.SITE_URL || "http://localhost:5173";

  return {
    statusCode: 302,
    headers: {
      Location: `${siteUrl}/#token=[REDACTED]}`,
    },
    body: "",
  };
};

export { handler };

import { useCallback, useSyncExternalStore } from "react";

function getSnapshot() {
  return window.location.search;
}

function subscribe(callback: () => void) {
  window.addEventListener("popstate", callback);
  return () => window.removeEventListener("popstate", callback);
}

/**
 * Read/write a single URL search parameter.
 * Updates the URL without a page reload and keeps state in sync across components.
 */
export function useSearchParam(key: string, defaultValue = ""): [string, (value: string) => void] {
  const search = useSyncExternalStore(subscribe, getSnapshot);
  const params = new URLSearchParams(search);
  const value = params.get(key) ?? defaultValue;

  const setValue = useCallback(
    (next: string) => {
      const p = new URLSearchParams(window.location.search);
      if (next === defaultValue || next === "") {
        p.delete(key);
      } else {
        p.set(key, next);
      }
      const qs = p.toString();
      const url = qs ? `${window.location.pathname}?${qs}` : window.location.pathname;
      window.history.pushState(null, "", url);
      // Notify all subscribers
      window.dispatchEvent(new PopStateEvent("popstate"));
    },
    [key, defaultValue],
  );

  return [value, setValue];
}

/** Boolean variant — stores "1" / absent. */
export function useSearchParamBool(key: string, defaultValue = false): [boolean, (value: boolean) => void] {
  const [raw, setRaw] = useSearchParam(key, defaultValue ? "1" : "");
  const value = raw === "1";
  const setValue = useCallback((v: boolean) => setRaw(v ? "1" : ""), [setRaw]);
  return [value, setValue];
}

import type { AuthorMergeStats, PRDetails } from "./github";
import { MERGE_STATS_CACHE_TTL_MS } from "../constants";

const AUTHOR_STATS_KEY = "merge-author-stats";
const PR_DETAILS_KEY = "merge-pr-details";
const ORG_MEMBERS_KEY = "merge-org-members";
const AUTHOR_CREATED_DATES_KEY = "merge-author-created-dates";

interface CachedAuthorStats {
  timestamp: number;
  data: Record<string, AuthorMergeStats>;
}

export function getCachedAuthorStats(): Map<string, AuthorMergeStats> | null {
  try {
    const raw = localStorage.getItem(AUTHOR_STATS_KEY);
    if (!raw) return null;
    const cached: CachedAuthorStats = JSON.parse(raw);
    if (Date.now() - cached.timestamp > MERGE_STATS_CACHE_TTL_MS) return null;
    return new Map(Object.entries(cached.data));
  } catch {
    return null;
  }
}

export function setCachedAuthorStats(stats: Map<string, AuthorMergeStats>): void {
  const cached: CachedAuthorStats = {
    timestamp: Date.now(),
    data: Object.fromEntries(stats),
  };
  localStorage.setItem(AUTHOR_STATS_KEY, JSON.stringify(cached));
}

interface CachedOrgMembers {
  timestamp: number;
  data: string[];
}

export function getCachedOrgMembers(): Set<string> | null {
  try {
    const raw = localStorage.getItem(ORG_MEMBERS_KEY);
    if (!raw) return null;
    const cached: CachedOrgMembers = JSON.parse(raw);
    if (Date.now() - cached.timestamp > MERGE_STATS_CACHE_TTL_MS) return null;
    return new Set(cached.data);
  } catch {
    return null;
  }
}

export function setCachedOrgMembers(members: Set<string>): void {
  const cached: CachedOrgMembers = {
    timestamp: Date.now(),
    data: [...members],
  };
  localStorage.setItem(ORG_MEMBERS_KEY, JSON.stringify(cached));
}

interface CachedAuthorCreatedDates {
  timestamp: number;
  data: Record<string, string>;
}

export function getCachedAuthorCreatedDates(): Map<string, string> | null {
  try {
    const raw = localStorage.getItem(AUTHOR_CREATED_DATES_KEY);
    if (!raw) return null;
    const cached: CachedAuthorCreatedDates = JSON.parse(raw);
    if (Date.now() - cached.timestamp > MERGE_STATS_CACHE_TTL_MS) return null;
    return new Map(Object.entries(cached.data));
  } catch {
    return null;
  }
}

export function setCachedAuthorCreatedDates(dates: Map<string, string>): void {
  const cached: CachedAuthorCreatedDates = {
    timestamp: Date.now(),
    data: Object.fromEntries(dates),
  };
  localStorage.setItem(AUTHOR_CREATED_DATES_KEY, JSON.stringify(cached));
}

export function getCachedPRDetails(): Map<number, PRDetails> {
  try {
    const raw = localStorage.getItem(PR_DETAILS_KEY);
    if (!raw) return new Map();
    const entries: Array<[number, PRDetails]> = JSON.parse(raw);
    return new Map(entries);
  } catch {
    return new Map();
  }
}

export function setCachedPRDetails(
  details: Map<number, PRDetails>,
  openPRNumbers: number[],
): void {
  const openSet = new Set(openPRNumbers);
  const pruned = new Map<number, PRDetails>();
  for (const [num, d] of details) {
    if (openSet.has(num)) pruned.set(num, d);
  }
  localStorage.setItem(PR_DETAILS_KEY, JSON.stringify([...pruned]));
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";

export default defineConfig({
  plugins: [react(), tailwindcss()],
});

import { useAuth } from "./hooks/useAuth";
import { usePullRequests } from "./hooks/usePullRequests";
import { TokenContext } from "./contexts/TokenContext";
import LoginScreen from "./components/LoginScreen";
import Header from "./components/Header";
import Board from "./components/Board";
import Spinner from "./components/Spinner";

export default function App() {
  const { token, user, loading: authLoading, login, logout } = useAuth();
  const {
    columns,
    authors,
    allLabels,
    assignees,
    loading: prLoading,
    error,
    lastUpdated,
    refresh,
    sortByScore,
    setSortByScore,
  } = usePullRequests(token);

  if (authLoading) {
    return <Spinner />;
  }

  if (!token || !user) {
    return <LoginScreen onLogin={login} />;
  }

  return (
    <TokenContext.Provider value={token}>
      <div className="flex h-screen flex-col bg-surface-0">
        <Header
          user={user}
          lastUpdated={lastUpdated}
          loading={prLoading}
          onRefresh={refresh}
          onLogout={logout}
        />
        {error && (
          <div className="mx-5 mt-3 rounded-lg border border-red-500/20 bg-red-500/10 px-4 py-2 text-sm text-red-400">
            {error}
          </div>
        )}
        {prLoading && columns.every((c) => c.prs.length === 0) ? (
          <Spinner />
        ) : (
          <Board columns={columns} authors={authors} allLabels={allLabels} assignees={assignees} currentUser={user.login} sortByScore={sortByScore} onSortToggle={() => setSortByScore(!sortByScore)} />
        )}
      </div>
    </TokenContext.Provider>
  );
}

